def gauss_model(mu, s, betas):
    ab = np.cumprod(1 - np.asarray(betas, float)); mu = np.asarray(mu, float)
    def f(x, t):
        a = ab[t - 1]
        return np.sqrt(1 - a) * (x - np.sqrt(a) * mu) / (a * s * s + 1 - a)
    return f
